using System.Collections.Generic;
using UnityEngine;
using NursingQuiz.Core;

namespace NursingQuiz.Data
{
    /// <summary>
    /// A collection of questions for one aihe + aihekori + tier combination.
    /// Generated by QuestionBankImporter -- one asset per source CSV file.
    /// </summary>
    public class QuestionBank : ScriptableObject
    {
        public string aihe;
        public string aihekori;
        public DifficultyTier tier;
        public string sourceFileName;

        [Tooltip("This tier's learning objective (Oppimistavoite), shown to the player once they've picked this difficulty.")]
        [TextArea(2, 6)]
        public string oppimistavoite;

        public List<QuestionData> questions = new List<QuestionData>();
    }
}
